import json, re, collections, datetime, sys

SRC = 'commits.jsonl'
OUT = 'RELEASE_NOTES.md'
LIMIT = 100

hdr_re = re.compile(r'^([a-z]+)(?:\(([^()\s]+)\))?(!)?: (.+)$')
co_re = re.compile(r'^Co-authored-by: (.+) <(.+)>$')
rev_re = re.compile(r'This reverts commit ([0-9a-f]{40})\.')

# .mailmap: "Proper Name <email> <alias>"
mailmap = {}
for line in open('.mailmap', encoding='utf-8'):
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    m = re.match(r'^(.*?) <([^>]+)>(?: <([^>]+)>)?$', line)
    name, email, alias = m.group(1), m.group(2).lower(), m.group(3)
    mailmap[email] = name
    if alias:
        mailmap[alias.lower()] = name


def canon(name, email):
    return mailmap.get(email.lower(), name)


rows = [json.loads(l) for l in open(SRC, encoding='utf-8') if l.strip()]

# Reverts: commit ids of reverted commits
reverted = set()
for r in rows:
    for line in r['message'].splitlines():
        m = rev_re.search(line)
        if m:
            reverted.add(m.group(1))

SECTION_ORDER = ['Breaking changes', 'Features', 'Fixes']
sec_of_type = {'feat': 'Features', 'fix': 'Fixes', 'perf': 'Features'}

entries = []
for r in rows:
    msg = r['message']
    lines = msg.splitlines()
    header = lines[0]
    m = hdr_re.match(header)
    if not m:
        continue
    typ, scope, bang, summary = m.group(1), m.group(2) or 'general', bool(m.group(3)), m.group(4)
    if r['hash'] in reverted:
        continue
    if bang:
        section = 'Breaking changes'
    elif typ in sec_of_type:
        section = sec_of_type[typ]
    else:
        continue
    if scope == 'internal' and not bang:
        continue
    if typ == 'perf':
        summary = summary + ' [perf]'
    summary = summary[0].upper() + summary[1:]
    if summary.endswith('.'):
        summary = summary[:-1]
    if scope == 'deps':
        scope = 'dependencies'
    issues = []
    if typ == 'fix':
        for line in lines[1:]:
            im = re.fullmatch(r'Fixes #(\d+)', line)
            if im:
                issues.append(im.group(1))
    when = datetime.datetime.fromisoformat(r['date'])
    assert when.tzinfo is not None
    entries.append({
        'hash': r['hash'], 'section': section, 'scope': scope, 'summary': summary,
        'issues': issues, 'when': when, 'author': canon(r['author'], r['email']),
        'coauthors': [],
        'row': r,
    })
    for line in lines[1:]:
        cm = co_re.match(line)
        if cm:
            entries[-1]['coauthors'].append(canon(cm.group(1).strip(), cm.group(2).strip()))

# merge by (section, scope, final summary)
groups = collections.OrderedDict()
for e in entries:
    groups.setdefault((e['section'], e['scope'], e['summary']), []).append(e)


def build(entry_commits, scope, summary):
    ordered = sorted(entry_commits, key=lambda e: e['when'], reverse=True)
    nums = []
    for e in ordered:
        for n in e['issues']:
            if n not in nums:
                nums.append(n)
    hashes = [e['hash'][:7] for e in ordered]
    prefix = f"- **{scope}:** "
    suffix = ''
    if nums:
        suffix += ' (' + ', '.join('#' + n for n in nums) + ')'
    suffix += ' (' + ', '.join(hashes) + ')'
    line = prefix + summary + suffix
    if len(line) > LIMIT:
        room = LIMIT - len(prefix) - len(suffix) - 1  # room for prefix of summary
        cut = summary
        while True:
            cand = summary[:room].rstrip(' ') + '\u2026'
            if len(prefix + cand + suffix) <= LIMIT:
                cut = cand
                break
            room -= 1
        line = prefix + cut + suffix
    return line, ordered[0]['when']


lines_by_section = collections.defaultdict(list)
for (section, scope, summary), cs in groups.items():
    line, newest = build(cs, scope, summary)
    lines_by_section[section].append((scope, newest, line))

out = ['# Release 4.2.0', '']
for section in SECTION_ORDER:
    items = lines_by_section.get(section)
    if not items:
        continue
    items.sort(key=lambda t: (t[0], -t[1].timestamp()))
    out.append('## ' + section)
    out.append('')
    out.extend(t[2] for t in items)
    out.append('')

# Contributors
authored = {e['author'] for e in entries}
credit = collections.Counter()
for e in entries:
    for name in set([e['author']] + e['coauthors']):
        if name.endswith('[bot]'):
            continue
        credit[name] += 1
people = [(n, c) for n, c in credit.items() if n in authored]
people.sort(key=lambda t: (-t[1], t[0]))
if people:
    out.append('## Contributors')
    out.append('')
    out.extend(f'- {n} ({c})' for n, c in people)

text = '\n'.join(out)
if not text.endswith('\n'):
    text += '\n'
open(OUT, 'w', encoding='utf-8', newline='\n').write(text)
print('wrote', OUT, len(out), 'lines')

